CREATE TABLE annotations(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,fingerprint TEXT NOT NULL,page_index INTEGER NOT NULL CHECK(page_index>=0),quote TEXT NOT NULL,quote_search TEXT NOT NULL,prefix TEXT NOT NULL,suffix TEXT NOT NULL,char_start INTEGER NOT NULL,char_end INTEGER NOT NULL,boxes TEXT NOT NULL,engine_version TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('underline','highlight','region')),color TEXT NOT NULL,line_count INTEGER NOT NULL,provenance TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,deleted INTEGER NOT NULL DEFAULT 0);
CREATE INDEX annotation_page ON annotations(document_id,deleted,page_index,created_at,id);
CREATE INDEX annotation_date ON annotations(document_id,deleted,created_at,id);
CREATE TABLE annotation_ranges(annotation_id TEXT NOT NULL REFERENCES annotations(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,c0 REAL NOT NULL,c1 REAL NOT NULL,c2 REAL NOT NULL,c3 REAL NOT NULL,c4 REAL NOT NULL,c5 REAL NOT NULL,c6 REAL NOT NULL,c7 REAL NOT NULL,PRIMARY KEY(annotation_id,ordinal));
